import { useState } from 'react';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { useAsOf } from './useAsOf';

/** Shows the sheet as of a date on this user's screen (or as it stands, when cleared), and the
 *  date it is shown as of. */
function AsOfPicker() {
  const [asOf, setAsOf] = useAsOf();
  const [date, setDate] = useState('');

  return (
    <form
      data-testid="asof-form"
      onSubmit={(e) => {
        e.preventDefault();
        const trimmed = date.trim();
        if (/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) setAsOf(trimmed);
      }}
    >
      As of: <strong data-testid="sheet-asof">{asOf}</strong>{' '}
      <label>
        Show as of{' '}
        <input
          data-testid="asof-date"
          placeholder="yyyy-mm-dd"
          value={date}
          onChange={(e) => setDate(e.target.value)}
        />
      </label>{' '}
      <button type="submit" data-testid="asof-set">
        Set
      </button>{' '}
      <button type="button" data-testid="asof-clear" onClick={() => setAsOf(undefined)}>
        Clear
      </button>
    </form>
  );
}

export const contribution = SheetPanels.fill({ order: 1, Component: AsOfPicker });
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { claimsKey } from '../claims/useClaims';
import { peopleKey } from '../people/usePeople';
import { periodsKey } from '../periods/usePeriods';
import { settingsKey, useSettings } from '../settings/useSettings';
import { sheetKey, useSheet, type Sheet } from './useSheet';

/** Shows the sheet's today and changes it; shows its parent sheet (nothing when none); shows whether the sheet is archived and archives it (a
 *  steward only); clones the sheet to another, never used, id (a steward only) and shows the last clone made. All share the sheet's error. */
function SheetToday({ user, sheet }: { user: string; sheet: string }) {
  const queryClient = useQueryClient();
  const { data } = useSheet(sheet);
  const { data: settings } = useSettings(sheet);
  const [date, setDate] = useState('');
  const [cloneTo, setCloneTo] = useState('');
  const submitOnce = useSubmitOnce();
  const save = useMutation({
    mutationFn: (today: string) =>
      postJson<Sheet>(`/api/sheets/${encodeURIComponent(sheet)}/today`, { today, user }),
    onSuccess: (saved) => {
      queryClient.setQueryData(sheetKey(sheet), saved);
      // A blank policy date is the sheet's today: it decides how each claim's live figures round.
      // The dated settings show (and the clerk limit and cap apply) as in force on the sheet's today.
      return Promise.all([
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: settingsKey(sheet) }),
        // A today past a period's grace days closes it.
        queryClient.invalidateQueries({ queryKey: periodsKey(sheet) }),
        // A moved today keeps a snapshot line on each person.
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
      ]);
    },
  });
  const archive = useMutation({
    mutationFn: () => postJson<Sheet>(`/api/sheets/${encodeURIComponent(sheet)}/archive`, { user }),
    onSuccess: (saved) => {
      queryClient.setQueryData(sheetKey(sheet), saved);
    },
  });
  const clone = useMutation({
    mutationFn: (to: string) => postJson<Sheet>(`/api/sheets/${encodeURIComponent(sheet)}/clone`, { to, user }),
  });

  return (
    <form
      data-testid="sheet-today-form"
      onSubmit={(e) => {
        e.preventDefault();
        archive.reset();
        clone.reset();
        submitOnce(() => save.mutateAsync(date.trim()));
      }}
    >
      Today: <strong data-testid="sheet-today">{data?.today ?? ''}</strong>{' '}
      <label>
        Set today{' '}
        <input
          data-testid="sheet-today-input"
          placeholder="yyyy-mm-dd"
          value={date}
          onChange={(e) => {
            setDate(e.target.value);
            save.reset();
            archive.reset();
            clone.reset();
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
        Save
      </button>
      {' '}Parent: <strong data-testid="sheet-parent">{settings?.parent ?? ''}</strong>{' '}
      {' '}Archived: <strong data-testid="sheet-archived">{data ? (data.archived ? 'yes' : 'no') : ''}</strong>{' '}
      <button
        type="button"
        data-testid="sheet-archive"
        disabled={archive.isPending}
        onClick={() => {
          save.reset();
          archive.reset();
          clone.reset();
          submitOnce(() => archive.mutateAsync());
        }}
      >
        Archive
      </button>{' '}
      <label>
        Clone to{' '}
        <input
          data-testid="sheet-clone-to"
          placeholder="Sheet id"
          value={cloneTo}
          onChange={(e) => {
            setCloneTo(e.target.value);
            save.reset();
            archive.reset();
            clone.reset();
          }}
        />
      </label>{' '}
      <button
        type="button"
        data-testid="sheet-clone"
        disabled={clone.isPending}
        onClick={() => {
          save.reset();
          archive.reset();
          clone.reset();
          submitOnce(() => clone.mutateAsync(cloneTo.trim()));
        }}
      >
        Clone
      </button>
      {' '}Cloned to: <strong data-testid="sheet-cloned-to">{clone.data?.id ?? ''}</strong>
      {(save.isError || archive.isError || clone.isError) && (
        <span data-testid="sheet-error" role="alert">
          {' '}
          {clone.isError
            ? 'Could not clone: only a steward can clone the sheet, to an id never used.'
            : archive.isError
            ? data?.archived
              ? 'Could not archive: the sheet is already archived.'
              : 'Could not archive: only a steward can archive the sheet.'
            : data?.archived
              ? 'Could not set today: the sheet is archived.'
              : 'Could not set today: enter a date as yyyy-mm-dd.'}
        </span>
      )}
    </form>
  );
}

export const contribution = SheetPanels.fill({ order: 0, Component: SheetToday });
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
export class HttpError extends Error {
  constructor(message: string, readonly status: number, readonly body: string) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  // While this screen shows the sheet as of a date (the `asof` search param, see
  // features/asof/useAsOf.ts) every change is refused, before it reaches the store.
  if (init?.method !== undefined && init.method !== 'GET' && asOfSet()) {
    throw new HttpError(`${init.method} ${path} refused: the sheet is shown as of a date`, 409, '');
  }
  const res = await fetch(path, init);
  if (!res.ok) {
    const body = await res.text().catch(() => '');
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status, body);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

function asOfSet(): boolean {
  return (new URLSearchParams(window.location.search).get('asof') ?? '') !== '';
}
import { useNavigate, useSearch } from '@tanstack/react-router';

/**
 * Read and write ONE search-param key.
 *
 * State that outlives a click lives in the URL, not in a parent component — a filter, a sort, a
 * toggle, which row is selected. The control that owns a key is a self-contained file, and whoever
 * reads the key does so directly. Search params are an open namespace (declared once in
 * routes/__root.tsx), so a new key needs no schema change.
 *
 *     const [status, setStatus] = useSearchParam('status', asString);
 */
export function useSearchParam<T>(
  key: string,
  decode: (raw: unknown) => T,
): [T, (value: T | undefined) => void] {
  const search = useSearch({ strict: false }) as Record<string, unknown>;
  const navigate = useNavigate();

  const set = (value: T | undefined) => {
    void navigate({
      to: '.', // stay on the current route; only the search changes
      // Only the one key changes; every other param is left exactly as it was, so two controls
      // never clobber each other.
      search: (prev: Record<string, unknown>) => {
        const next = { ...prev };
        if (value === undefined || value === '') {
          delete next[key];
        } else {
          next[key] = value;
        }
        return next;
      },
      replace: true,
    });
  };

  return [decode(search[key]), set];
}

export const asString = (raw: unknown): string => (typeof raw === 'string' ? raw : '');
export const asNumber = (raw: unknown): number | undefined => {
  const n = Number(raw);
  return raw === undefined || raw === '' || Number.isNaN(n) ? undefined : n;
};
export const asFlag = (raw: unknown): boolean => raw === 'true' || raw === true;
