import { asString, useSearchParam } from '../../url/useSearchParam';

/**
 * The date this user's screen shows the sheet as of (yyyy-mm-dd), or '' for the sheet as it stands.
 * It lives in the URL (`asof`), so it is this screen's alone. While it is set every read is of the
 * sheet as it stood at the end of that date, and every change is refused (see api/http.ts).
 */
export function useAsOf(): [string, (value: string | undefined) => void] {
  const [asOf, setAsOf] = useSearchParam('asof', asString);
  return [asOf, setAsOf];
}

/** A read's query key: the live key, or one apart from it for the sheet as of a date. It keeps the
 *  live key as its prefix, so invalidating the live key re-reads both. */
export function asOfKey<K extends readonly unknown[]>(key: K, asOf: string): K {
  return (asOf === '' ? key : [...key, { asOf }]) as unknown as K;
}

/** A read's path, asking for the sheet as of the date when one is set. */
export function asOfPath(path: string, asOf: string): string {
  return asOf === '' ? path : `${path}${path.includes('?') ? '&' : '?'}asOf=${encodeURIComponent(asOf)}`;
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { dueCents, hundredths, roundTenThousandths } from '../rates/useRates';
import type { FloorOn } from '../settings/useSettings';
import { asOfKey, asOfPath, useAsOf } from '../asof/useAsOf';

/** Where a claim is in its life: DRAFT → OPEN → SETTLED (or, settled by a clerk over the clerk
 *  limit, OPEN → PENDING, which a steward approves to SETTLED or rejects back to OPEN), and DRAFT,
 *  OPEN or PENDING → VOID; a steward may void a SETTLED claim within 7 days of its settlement.
 *  A DRAFT whose due is above the sheet's review threshold on its date goes REVIEW when opened (no number
 *  yet) until a steward reviews it to OPEN; it can be voided, and counts in no total, only in the status counts.
 *  A DRAFT can be DELETED (and restored to DRAFT on the same sheet's today); a DELETED claim counts
 *  nowhere, not even in the status counts. */
export type ClaimStatus = 'DRAFT' | 'REVIEW' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED';

/** Every status that is counted, in life order — the order the summary and header list them in (not DELETED). */
export const STATUSES: readonly ClaimStatus[] = ['DRAFT', 'REVIEW', 'OPEN', 'PENDING', 'SETTLED', 'VOID'];

/** Whether a claim is still open: OPEN or PENDING. A PENDING claim is handled like an OPEN one: it
 *  goes overdue, bears the late charge, and a hold takes it out of the totals. */
export function isOpen(claim: Claim): boolean {
  return claim.status === 'OPEN' || claim.status === 'PENDING';
}

/** A claim as the server sends it: `amount` with two decimals, `date` as yyyy-mm-dd. */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  /** Given when the claim is opened (a voided claim keeps it); null for a DRAFT, or a claim voided while a DRAFT. Sheet-wide ("7"), or within its period ("P1-2", "X-1" in no period). */
  number: string | null;
  /** The due fixed when the claim was settled, two decimals; null when it has none, so its due is live. */
  due: string | null;
  /** The user who opened the claim; null while it has not been opened. */
  openedBy: string | null;
  /** Whether the person's last statement binds the claim to the figure it had then. */
  stated: boolean;
  /** The figure the last statement bound the claim to, two decimals; null when unbound or bound to n/a. */
  statedDue: string | null;
  /** The number of the SETTLED claim of the same person a correction (a negative amount) corrects; null for any other claim. */
  corrects: string | null;
  /** Whether the claim's live figures (its rate step and late charge) round half up, else half to
   *  even: half up when it is dated before the sheet's policy date (a correction goes by the date of
   *  the claim it corrects). */
  halfUp: boolean;
  /** The date the claim is due by (yyyy-mm-dd), fixed when it was added from the terms of its
   *  person's grade then; later changes to the terms or the claim's date leave it. */
  dueBy: string;
  /** The claim's status log, oldest first: one line per status it has had, as
   *  "<STATUS> by <user> on <date> due=<due>" (the sheet's today and the claim's due then). */
  log: string[];
  /** Whether the claim is deferred now: OPEN, and the sheet's today is before its deferred-until
   *  date. A deferred claim counts in no total, is not overdue and cannot be settled. */
  deferred: boolean;
  /** The date (yyyy-mm-dd) the claim was last deferred until (kept once that date is reached); null when it never was. */
  deferredUntil: string | null;
  /** How many proofs the claim has: one whose due is above the sheet's proof threshold on its date
   *  cannot be settled or approved while it has none (nor while it lacks one of each of the sheet's proof kinds). */
  proofs: number;
  /** How many of its proofs are receipts (a proof added with no kind chosen is a receipt). */
  proofReceipts: number;
  /** How many of its proofs are photos. */
  proofPhotos: number;
  /** The number of the claim this one was split off; null when it was not split off one. */
  splitFrom: string | null;
  /** The user whose open editor locks the claim for everyone else; null when no editor holds it. */
  lockedBy: string | null;
  /** Whether the claim was added while its period was soft-closed. */
  lateEntry: boolean;
  /** The last day (yyyy-mm-dd) a reminder was written for the claim; null when it never was. */
  remindedOn: string | null;
  /** Whether a steward has waived the claim's late charge: it bears none from then on. */
  waived: boolean;
  /** Whether the claim is held: while OPEN or PENDING it counts in no live due figure (claimed still counts it), unless a statement binds it. */
  held: boolean;
  /** The claim's external reference, unique on the sheet without regard to case; null when it has none. */
  ref: string | null;
  /** The claim's tags, lower-cased and sorted; empty when it has none. */
  tags: string[];
  /** Every tag the claim has ever carried (its tags now among them). */
  tagsUsed: string[];
  /** The reason from the sheet's list the claim was voided with; null when none was given. */
  voidReason: string | null;
  /** The claim's comments, oldest first, as "<user> on <date>: <text>" (the sheet's today when it was written). */
  comments: string[];
  /** The claim's lines, in the order added, as "<label> <qty> x <unit>"; its amount is them added up. */
  lines: string[];
  /** The number of the bulk settle batch (1, 2, ... on the sheet) that settled the claim (or sent it PENDING); null when none did. */
  batch: number | null;
  /** The order the claim was added in: a forward-only rate applies only to claims added after it was saved (see `claimRateOn`). */
  seq: number;
  /** The people the claim is shared with, in the order shared, each holding `share` (a percent, two
   *  decimals) of its due: their part counts in their figures, and the claim's own person's in place. */
  shares: { personId: number; share: string }[];
  /** The user a steward assigned the claim's review to; null when none. */
  reviewAssigned: string | null;
};

export const claimsKey = (sheet: string) => ['sheet', sheet, 'claims'] as const;

/** Every claim on the sheet, newest first, re-read whenever the sheet is loaded. */
export function useClaims(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(claimsKey(sheet), asOf),
    queryFn: () => getJson<Claim[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/claims`, asOf)),
    staleTime: 0,
    gcTime: 0,
  });
}

/** The number of the sheet's last bulk settle batch; null when there has been none. */
export function lastBatch(claims: Claim[]): number | null {
  return claims.reduce<number | null>((last, c) => (c.batch != null && (last == null || c.batch > last) ? c.batch : last), null);
}

/** An amount the server accepts: up to two decimals; negative only for a correction. */
export const AMOUNT = /^-?\d+(\.\d{1,2})?$/;

/** A correction's `corrects`: the number of the claim it corrects. */
export const CLAIM_NUMBER = /^(\d+|.+-\d+)$/;

/** Whether a claim is a correction: its amount is negative. Its due has no floor and no late charge. */
export function isCorrection(claim: Claim): boolean {
  return claim.amount.startsWith('-');
}

/** The claims that count toward claimed, due-total and every total: OPEN, PENDING and SETTLED ones. */
export function counted(claims: Claim[]): Claim[] {
  return claims.filter((c) => isOpen(c) || c.status === 'SETTLED');
}

/** The claims that count in the live totals: OPEN, PENDING and SETTLED ones, but not deferred ones,
 *  nor the OPEN or PENDING ones of a retired person (`heldOn` tells, by person id and date),
 *  unless a statement binds them. */
export function live(claims: Claim[], heldOn: (personId: number, date: string) => boolean): Claim[] {
  return counted(claims).filter(
    (c) => !c.deferred && (!isOpen(c) || c.stated || !heldOn(c.personId, c.date)),
  );
}

/** The claims that count toward claimed: as `live`, but a hold (the claim's or its person's) does not
 *  take one out — only its due leaves the totals while held. `retiredOn` tells, by person id, whether
 *  the person's retirement takes their OPEN or PENDING claims out, unless a statement binds them. */
export function claimedLive(claims: Claim[], retiredOn: (personId: number) => boolean): Claim[] {
  return counted(claims).filter((c) => !c.deferred && (!isOpen(c) || c.stated || !retiredOn(c.personId)));
}

/** The sum of these claims' amounts, leaving out those that correct another, with two decimals.
 *  Added up in cents, so it is exact. */
export function claimed(claims: Claim[]): string {
  const cents = claims.filter((c) => c.corrects === null).reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}

/** What is due on one claim, in cents: the due fixed when it was settled, or else the due its person's
 *  last statement bound it to (as shown then, late charge and floor included), or else the greater of the
 *  sheet's `floor` on the claim's date and its figure live at `pct`, plus the late charge on that floored figure (null, n/a, when there is no rate). A correction has
 *  neither floor nor charge. */
export function claimDueCents(claim: Claim, floor: FloorOn, pct: string | undefined, late?: Late): bigint | null {
  if (claim.due !== null) return hundredths(claim.due);
  const figure = claimFigureCents(claim, pct);
  // A bound due already holds the late charge and floor it had when the statement was taken.
  if (figure === null || claim.stated || isCorrection(claim)) return figure;
  const least = hundredths(floor(claim.date));
  const floored = figure < least ? least : figure;
  return late === undefined ? floored : floored + lateChargeCents(claim, floored, late);
}

/** A claim's figure, in cents: the due its person's last statement bound it to, or else live at `pct` (null, n/a, when there is no rate).
 *  A PENDING claim is bound by a statement like any other: it shows its bound figure. */
function claimFigureCents(claim: Claim, pct: string | undefined): bigint | null {
  if (claim.stated) return claim.statedDue !== null ? hundredths(claim.statedDue) : null;
  return dueCents(claim.amount, pct, claim.halfUp);
}

/** What makes an overdue claim's due grow: the sheet's `today` and its late percent in force on a
 *  date, `pctOn`; and the grace days a claim has past its due-by, `graceOn` (none when not given). */
export type Late = { today: string; pctOn: (date: string) => string; graceOn?: (claim: Claim) => number };

/** Whole days from one yyyy-mm-dd to another. */
function daysBetween(from: string, to: string): number {
  return Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86_400_000);
}

/** The yyyy-mm-dd `days` days after `date`. */
function addDays(date: string, days: number): string {
  return new Date(Date.parse(`${date}T00:00:00Z`) + days * 86_400_000).toISOString().slice(0, 10);
}

/** The date a claim goes overdue after: its due-by plus its grace days. */
export function overdueFrom(claim: Claim, late: Late): string {
  return addDays(claim.dueBy, late.graceOn?.(claim) ?? 0);
}

/** The late charge on an overdue claim's `figure`, in cents: for every full 30 days it is overdue,
 *  counted from its due-by plus its grace, the late percent in force on that boundary date (the due-by
 *  plus the grace plus 30, 60, 90 ... days) of it plus the charges of the boundaries before it (compounding), each
 *  rounded by the claim's rounding (`halfUp`), added up; a boundary at 0.00 adds nothing. Nothing
 *  while it is not overdue, or its charge is waived. It follows the sheet's today; a statement binds it into the claim's due. */
export function lateChargeCents(claim: Claim, figure: bigint, late: Late): bigint {
  if (!overdue(claim, late) || isCorrection(claim) || claim.waived) return 0n;
  const from = overdueFrom(claim, late);
  const periods = Math.floor(daysBetween(from, late.today) / 30);
  let total = 0n;
  for (let k = 1; k <= periods; k++) {
    const pct = hundredths(late.pctOn(addDays(from, 30 * k)));
    if (pct === 0n) continue;
    // cents * hundredths-of-a-percent is in ten-thousandths of a cent.
    total += roundTenThousandths((figure + total) * pct, claim.halfUp);
  }
  return total;
}


/** A share holder's part of a claim's due, in cents: the due times their share divided by 100,
 *  rounded half to even (on its size, so a negative due rounds like a positive one). */
export function partCents(due: bigint, share: string): bigint {
  const product = due * hundredths(share);
  const rounded = roundTenThousandths(product < 0n ? -product : product, false);
  return product < 0n ? -rounded : rounded;
}

/** The claims in a person's figures: their own, and those shared with them. */
export function carried(claims: Claim[], personId: number): Claim[] {
  return claims.filter((c) => c.personId === personId || c.shares.some((s) => s.personId === personId));
}

/** What of a claim's due a person carries, in cents: its own person the due less the holders' parts, a holder their part. */
export function carriedCents(claim: Claim, due: bigint, personId: number): bigint {
  if (claim.personId === personId) return claim.shares.reduce((rest, s) => rest - partCents(due, s.share), due);
  const held = claim.shares.find((s) => s.personId === personId);
  return held === undefined ? 0n : partCents(due, held.share);
}

/** A person's due-total, in cents: the sum of their counted claims' figures, each already rounded —
 *  a settled claim's fixed due, else the figure a statement bound it to, else live at `pctOn(claim)` (the rate that applies to it on its date), plus any late charge and at least `floor`, the rate in force on the claim's
 *  date (at `pct`, the rate in force on the sheet's today, when no `pctOn` is given). 0 with
 *  nothing that counts. With `late`, an overdue claim's late charge is added on top. Null (n/a) when there is no rate today, unless some settled claim keeps a
 *  figure: then it is the sum of the figures there are. With `cap`, it is at most the cap less `cut`, the
 *  person's cut total in cents (not below 0; an n/a one is not capped). With `personId`, the claims are those the person carries (see `carried`), each
 *  counting what of its due they carry (see `carriedCents`); `pctOn` then gives each claim's rate by its own person. */
export function personDueCents(claims: Claim[], floor: FloorOn, pct: string | undefined, pctOn?: (claim: Claim) => string | undefined, late?: Late, cap?: string | null, personId?: number, cut?: bigint): bigint | null {
  let sum = 0n;
  let any = false;
  for (const c of counted(claims)) {
    const due = claimDueCents(c, floor, pctOn ? pctOn(c) : pct, late);
    if (due === null) continue;
    sum += personId === undefined ? due : carriedCents(c, due, personId);
    any = true;
  }
  if (pct === undefined && !any) return null;
  return capCents(sum, cap, cut);
}

/** A due-total at most the sheet's `cap` less the person's `cut` total in cents (not below 0; null or
 *  blank cap: no cap); n/a is not capped. */
export function capCents(due: bigint | null, cap?: string | null, cut: bigint = 0n): bigint | null {
  if (due === null || cap == null || cap === '') return due;
  const less = hundredths(cap) - cut;
  const most = less > 0n ? less : 0n;
  return due > most ? most : due;
}

/** How much a due-total plus the person's `cut` total is over the sheet's `cap`: 0 when it is not (or
 *  the due-total is n/a, or there is no cap). */
export function excessCents(due: bigint | null, cap?: string | null, cut: bigint = 0n): bigint {
  if (due === null || cap == null || cap === '') return 0n;
  const over = due + cut - hundredths(cap);
  return over > 0n ? over : 0n;
}

/** Whether a claim is overdue: it is OPEN (or PENDING), not deferred, and its due-by plus its grace
 *  days is before the sheet's today. */
export function overdue(claim: Claim, late: Late): boolean {
  return isOpen(claim) && !claim.deferred && late.today !== '' && overdueFrom(claim, late) < late.today;
}

/** These claims' overdue ones: their count, and their dues with late charges added up in cents (n/a ones skipped).
 *  `pctOn` is the rate that applies to a claim on its date. */
export function overdueFigures(claims: Claim[], late: Late, floor: FloorOn, pctOn: (claim: Claim) => string | undefined): { count: number; cents: bigint } {
  const over = claims.filter((c) => overdue(c, late));
  const cents = over.reduce<bigint>((sum, c) => sum + (claimDueCents(c, floor, pctOn(c), late) ?? 0n), 0n);
  return { count: over.length, cents };
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, useAsOf } from '../asof/useAsOf';

/** `version` counts the person's saves; an edit sends the version it loaded, so a save made by
 *  someone else in the meantime refuses it. `statementCount` is how many statements have been
 *  taken for them; `statedTotal` the last one's due-total (two decimals, null when it was n/a or
 *  none was taken) and `statementDate` its date (yyyy-mm-dd, null when none was taken).
 *  `retired` is whether a retirement date is set (whatever the date), `retiredFrom` that date
 *  (yyyy-mm-dd, null when not retired). `pastRetirements` are the retirements ended by unretiring
 *  them, in the order they ended, from the retirement date to the day unretired; no claim dated after
 *  the from and before the to of one is accepted. `held` is whether they have any hold; `holds` every hold, in the
 *  order added, from a date to a date (both inclusive; `to` null: open-ended). Their OPEN claims
 *  dated within a hold count in no live total, nor any OPEN or PENDING claim of theirs once the sheet's today
 *  reaches their retirement date, unless a statement binds them. `patrons` are the ids of the people they have named as patrons, in
 *  the order they were named. `grade` is the grade in force on the sheet's today when they were read;
 *  `grades` every grade recorded, by from-date (null: from the beginning of time, first). `terms` are
 *  the person's own terms in days in force on the sheet's today (null: none), ahead of their grade's
 *  and the sheet's; `ownTerms` their own terms from the beginning of time (null: none), and
 *  `datedTerms` every dated terms recorded, by from-date (`terms` null: none from then).
 *  `contact` is the person's contact, trimmed and lower-cased (null: none). `aliases` are the
 *  person's aliases, sorted as names are compared; the quick-add bar and the paste box find a
 *  person by an alias as well as by the name. `clashing` is whether their name or an alias is used
 *  on another sheet of the sheet's tree (its ancestors and descendants); such a person's edits are
 *  refused until one renames them to a name that does not clash. `origin` is the sheet the person
 *  was transferred from (null: they were not transferred here). `tags` are the person's tags,
 *  lower-cased and sorted (empty: none); a claim counts in a tag's total when it or its person carries it. */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: { grade: string; from: string | null }[];
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retired: boolean;
  retiredFrom: string | null;
  pastRetirements: { from: string; to: string }[];
  held: boolean;
  holds: { from: string; to: string | null }[];
  patrons: number[];
  terms: number | null;
  ownTerms: number | null;
  datedTerms: { terms: number | null; from: string }[];
  contact: string | null;
  aliases: string[];
  clashing: boolean;
  origin: string | null;
  tags: string[];
  /** Snapshot lines, oldest first: `<day left> <due-total>` (n/a when it was n/a). */
  snapshots: string[];
  /** Statements still standing, oldest first: `<statement date> <due-total>` (n/a when it was n/a). */
  statementLines: string[];
  /** The reason of the person's flag while it is in force (the sheet's today on or before its
   *  until-date), null when none is; only a steward may open their claims then. */
  flag: string | null;
  /** The user who may approve or reject the person's PENDING claims as a steward may, null when none. */
  approver: string | null;
};

/** Whether the sheet's `today` (yyyy-mm-dd) has reached the person's retirement date. */
export function retiredOut(person: Person, today: string): boolean {
  return person.retiredFrom !== null && today !== '' && today >= person.retiredFrom;
}

/** Whether a claim of the person's dated `date` (yyyy-mm-dd) is held out of the live totals: the sheet's
 *  `today` has reached their retirement date. A hold does not take a claim out (only a pool cut). */
export function heldOn(person: Person, _date: string, today: string): boolean {
  return retiredOut(person, today);
}

/** By person id, whether a claim dated then is held out (see `heldOn`) on the sheet's `today`. */
export function heldOnBy(people: Person[], today: string): (personId: number, date: string) => boolean {
  const byId = new Map(people.map((p) => [p.id, p]));
  return (personId, date) => {
    const p = byId.get(personId);
    return p !== undefined && heldOn(p, date, today);
  };
}

export const GRADES = ['A', 'B', 'C'] as const;

export const peopleKey = (sheet: string) => ['sheet', sheet, 'people'] as const;

/** The sheet's people in list order (by position; see the move buttons), re-read whenever the sheet is loaded. */
export function usePeople(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(peopleKey(sheet), asOf),
    queryFn: () => getJson<Person[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/people`, asOf)),
    staleTime: 0,
    gcTime: 0,
  });
}

/** The person's grade in force on `date` (yyyy-mm-dd): the one from the latest date on or before
 *  it, the first one they were given applying from the beginning of time. */
export function gradeOn(person: Person, date: string): string {
  let found = person.grades[0]?.grade ?? person.grade;
  for (const g of person.grades) if (g.from === null || g.from <= date) found = g.grade;
  return found;
}

/** How the screen shows a person's name: `<name> (<grade in force on date>)`. */
export function shownName(person: Person, date: string): string {
  return `${person.name} (${gradeOn(person, date)})`;
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, useAsOf } from '../asof/useAsOf';

/** `lastBatch`: the number of the sheet's last bulk settle batch, kept once its claims leave the sheet; null when none. */
export type Sheet = { id: string; today: string; archived: boolean; lastBatch: number | null };

export const sheetKey = (sheet: string) => ['sheet', sheet] as const;

/** The active sheet as the store holds it, re-read whenever the sheet is loaded. */
export function useSheet(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(sheetKey(sheet), asOf),
    queryFn: () => getJson<Sheet>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}`, asOf)),
    staleTime: 0,
    gcTime: 0,
  });
}

