            jdbc.update("INSERT INTO ASOF.\\"" + table + "\\" (" + names + ") SELECT " + names
                    + " FROM PUBLIC.\\"" + table + "\\" WHERE sheet_id = ?", sheetId);
        }
        ancestors(sheetId);
    }

