import { live, personDueCents, useClaims } from '../claims/useClaims';
import { GRADES, gradeOn, heldOn, usePeople } from '../people/usePeople';
import { claimRateOn, rateOn, useRates } from '../rates/useRates';
import { useCutTotal } from '../pools/usePools';
import { useCap, useFloor, useLate } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheet';

/**
 * Per grade, the people not retired on it on the sheet's today, each with their due-total in cents
 * (null when n/a), worked out as the list works it out. One place, so the summary and the
 * consolidated figures agree.
 */
export function useGradeDues(sheet: string) {
  const { data: all = [] } = useClaims(sheet);
  const { data: everyone = [] } = usePeople(sheet);
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  const cap = useCap(sheet);
  const cutOf = useCutTotal(sheet);
  const people = everyone.filter((p) => !p.retired);
  const dueOf = (p: (typeof people)[number]) =>
    personDueCents(
      live(all.filter((c) => c.personId === p.id), (_, date) => heldOn(p, date, today)),
      floor,
      rateOn(rates, gradeOn(p, today), today),
      (c) => claimRateOn(rates, gradeOn(p, c.date), c),
      late,
      cap,
      undefined,
      cutOf(p.id),
    );
  return Object.fromEntries(
    GRADES.map((g) => {
      const on = people.filter((p) => gradeOn(p, today) === g);
      return [g, on.map((p) => ({ person: p, due: dueOf(p) }))];
    }),
  ) as Record<(typeof GRADES)[number], Array<{ person: (typeof people)[number]; due: bigint | null }>>;
}
import { gradeOn, heldOnBy, retiredOut, usePeople } from '../people/usePeople';
import { claimRateOn, rateOn, totalDue, trimmedTotal, useRates } from '../rates/useRates';
import { useCutTotal } from '../pools/usePools';
import { useCap, useFloor, useLate } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheet';
import { carried, claimed, claimedLive, isOpen, live, overdueFigures, personDueCents, useClaims } from './useClaims';

/**
 * The sheet's totals: its claimed-total, everyone's counted (OPEN or SETTLED) claims added up
 * (held ones too, but not OPEN ones once their person retires, unless stated, nor those that correct another), and its due-total, everyone's due-total
 * added up (a person whose due-total is n/a is skipped), and how many of the claims that count are
 * overdue, with their dues added up. Both due and overdue totals leave out the single highest and
 * lowest person's figure when three or more people have one. Its settled-total and open-total are
 * everyone's due-total before the cap split into SETTLED and OPEN-or-PENDING claims, simply added up.
 * A person's figures carry their parts of the claims shared with them, and their own claims less the holders' parts. Each person's own figures too. One place, so every screen repeating a total shows the same figure.
 */
export function useSheetTotals(sheet: string) {
  const { data: all = [] } = useClaims(sheet);
  const { data: people = [] } = usePeople(sheet);
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const claims = live(all, heldOnBy(people, today));
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  const cap = useCap(sheet);
  const cutOf = useCutTotal(sheet);
  // A claim's rate by its own person's grade on its date (a share holder's part is of that due).
  const byId = new Map(people.map((p) => [p.id, p]));
  const ownRate = (c: (typeof claims)[number]) => {
    const owner = byId.get(c.personId);
    return owner === undefined ? undefined : claimRateOn(rates, gradeOn(owner, c.date), c);
  };
  const dues = people.map((p) =>
    personDueCents(carried(claims, p.id), floor, rateOn(rates, gradeOn(p, today), today), ownRate, late, cap, p.id, cutOf(p.id)),
  );
  // Everyone's due-total before the cap, split into its SETTLED and its OPEN-and-PENDING part.
  const part = (keep: (c: (typeof claims)[number]) => boolean) =>
    people.map((p) =>
      personDueCents(carried(claims, p.id).filter(keep), floor, rateOn(rates, gradeOn(p, today), today), ownRate, late, undefined, p.id),
    );
  const over = people.map((p) =>
    overdueFigures(claims.filter((c) => c.personId === p.id), late, floor, (c) => claimRateOn(rates, gradeOn(p, c.date), c)),
  );
  return {
    /** Each person's own due-total (capped) and overdue-total, in cents, in the people's order. */
    perPerson: people.map((p, i) => ({ person: p, due: dues[i], overdue: over[i].cents })),
    claimedTotal: claimed(claimedLive(all, (id) => people.some((p) => p.id === id && retiredOut(p, today)))),
    dueTotal: trimmedTotal(dues),
    settledTotal: totalDue(part((c) => c.status === 'SETTLED')),
    openTotal: totalDue(part(isOpen)),
    overdueCount: over.reduce((n, o) => n + o.count, 0),
    overdueTotal: trimmedTotal(over.map((o) => o.cents)),
  };
}
 * figure over the whole tree when three or more have one; per grade,
 * each sheet's due-totals of the people not retired on it (as its summary shows them), added up; and
 * per status, how many claims have it over the tree. While the
 * screen shows the sheet as of a date, every sheet of the tree is read as it stood at the end of that
 * date, with that date as its today. A sheet
 * with no children shows its own. Blank until every sheet's figures have loaded.
 */
function Consolidated({ sheet }: { user: string; sheet: string }) {
  const { data: descendants } = useDescendants(sheet);
  const sheets = descendants === undefined ? [] : [sheet, ...descendants];
  const [figures, setFigures] = useState<Record<string, Figures | null>>({});
  const report = useCallback((id: string, f: Figures | null) => {
    setFigures((was) => (same(was[id] ?? null, f) ? was : { ...was, [id]: f }));
  }, []);
  const all = sheets.map((id) => figures[id] ?? null);
  const ready = sheets.length > 0 && all.every((f) => f !== null);
  const loaded = all.filter((f): f is Figures => f !== null);
  return (
    <section data-testid="consolidated">
      {sheets.map((id) => (
        <SheetFigures key={id} sheet={id} report={report} />
      ))}
      <p>
        Consolidated: people <strong data-testid="consolidated-people-count">{ready ? distinctPeople(loaded.flatMap((f) => f.names)) : ''}</strong>
        , due <strong data-testid="consolidated-due-total">{ready ? trimmedTotal(loaded.flatMap((f) => f.dues.map(toCents))) : ''}</strong>
        , overdue <strong data-testid="consolidated-overdue-total">{ready ? trimmedTotal(loaded.flatMap((f) => f.overdues.map(toCents))) : ''}</strong>
      </p>
      <p>
        Due by grade:
        {GRADES.map((g) => (
          <span key={g}>
            {' '}
            {g} <strong data-testid={`consolidated-grade-${g}-due-total`}>{ready ? totalDue(loaded.map((f) => hundredths(f.grades[g]))) : ''}</strong>
          </span>
        ))}
      </p>
      <p>
        Claims by status:
        {STATUSES.map((s) => (
          <span key={s}>
            {' '}
            {s} <strong data-testid={`consolidated-status-${s}-count`}>{ready ? loaded.reduce((n, f) => n + f.statuses[s], 0) : ''}</strong>
          </span>
        ))}
      </p>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 21, Component: Consolidated });

